var e={theme:"Computational Intelligence for Smart Systems",alternativeTheme:"Intelligent Computing for a Smart World",about:"The International Conference on Intelligent Computing, Information and Communication Technologies (ICICIC 2027) brings together researchers, academicians, industry professionals and students to share original research and real-world innovation in intelligent computing, information systems and communication technologies, under the theme Computational Intelligence for Smart Systems.",aims:["Provide an international forum to present original, peer-reviewed research in computational intelligence and smart systems.","Connect academia, industry and government to turn research into practical, sustainable technology.","Encourage interdisciplinary work across computing, communication, energy, control and sensing.","Support early-career researchers and doctoral scholars through mentorship, feedback and publication.","Promote responsible and ethical use of AI and emerging technologies in society."],school:{name:"School of Science and Computer Studies (SSCS)",university:"CMR University, Bengaluru",overview:"The School of Science and Computer Studies (SSCS) at CMR University is dedicated to advancing technology-driven education and research. With specialised programmes in Computer Science, Data Science, Artificial Intelligence, Cybersecurity, Cloud Computing and Game Development, the School blends academic rigour with practical exposure to nurture future-ready professionals.",vision:"To provide high-quality education that develops globally competent technocrats and entrepreneurs in Computer Science and Technology, grounded in ethical values and equipped to meet the dynamic demands of industry and society.",mission:["Deliver value-based technical education in Computer Applications and Information Technology using modern infrastructure and pedagogical innovation.","Develop ethical and ambitious professionals through a blend of theory and practical application.","Build independent and collaborative problem-solving skills.","Create globally aware professionals who promote sustainable, environmentally conscious computing."],history:["Over the years, SSCS has forged partnerships with leading technology firms, contributed to impactful faculty and student research, and facilitated placements in reputed organisations.","The School hosts technical events, hackathons, gamethons and exhibitions, giving students platforms to demonstrate their expertise beyond the classroom."],historyTodo:"Organisers: add founding year and key milestones of SSCS here (not published on cmr.edu.in).",programmes:["BCA","BCA in Data Science","BCA in Cloud Computing","BCA in AI & ML","BCA in Game Development","B.Sc. IT (AI & ML)","MCA","MCA in AI & ML","M.Sc. IT (AI & ML)"],source:"https://cmr.edu.in/school/school-of-science-computer-studies/"},areasNote:"Topics are a draft for the organising committee to review.",areas:[{id:"computational-intelligence",title:"Computational Intelligence",icon:"fa-solid fa-brain",description:"Learning, reasoning and optimisation methods that make systems adaptive and intelligent.",topics:["Machine learning and deep learning","Neural networks","Fuzzy logic and soft computing","Evolutionary and swarm intelligence","Optimisation algorithms","Explainable and trustworthy AI"]},{id:"iot-cloud",title:"IoT & Cloud",icon:"fa-solid fa-cloud",description:"Connected devices, edge and cloud platforms that power smart systems at scale.",topics:["Internet of Things architectures","Edge and fog computing","Cloud and serverless computing","IoT security and privacy","Smart cities and smart homes","Digital twins"]},{id:"green-energy",title:"Green Energy Systems",icon:"fa-solid fa-leaf",description:"Intelligent technologies for sustainable, efficient and renewable energy.",topics:["Renewable energy integration","Smart grids and microgrids","Energy-efficient computing","Electric vehicles and charging","Energy forecasting with AI","Sustainable computing"]},{id:"cognitive-computing",title:"Advanced Cognitive Computing",icon:"fa-solid fa-lightbulb",description:"Systems that perceive, understand and interact in human-like ways.",topics:["Natural language processing","Computer vision","Knowledge representation and reasoning","Human\u2013computer interaction","Affective computing","Brain-inspired computing"]},{id:"genai",title:"Generative AI",icon:"fa-solid fa-wand-magic-sparkles",description:"Models that create text, images, code and data, and their responsible use.",topics:["Large language models","Diffusion and generative image models","Prompt engineering and agents","Retrieval-augmented generation","AI safety, ethics and governance","Generative AI in education and healthcare"]},{id:"control-instrumentation",title:"Control & Instrumentation",icon:"fa-solid fa-gauge-high",description:"Measurement, automation and control for intelligent industrial systems.",topics:["Intelligent and adaptive control","Industrial automation and Industry 4.0","Robotics and mechatronics","Process control","Embedded and cyber-physical systems","Biomedical instrumentation"]},{id:"sensors",title:"Sensors",icon:"fa-solid fa-satellite-dish",description:"Sensing technologies and networks that feed data to smart systems.",topics:["Wireless sensor networks","Smart and wearable sensors","Sensor fusion","Biosensors","Remote sensing","Sensor data analytics"]}]};var c={acronym:"ICICIC 2027",title:"International Conference on Intelligent Computing, Information and Communication Technologies (ICICIC 2027)",dates:"Oct 8-9, 2027",venue:"CMR University, Bengaluru, India",format:"Offline (in person)",email:"iccimr@cmr.edu.in",about:["The International Conference on Intelligent Computing, Information and Communication Technologies (ICICIC 2027) is a premier international forum dedicated to research excellence, innovation, and knowledge exchange across emerging areas of computing and communication technologies.","ICICIC connects researchers, academicians, industry professionals, and students through rigorous peer review, high-impact technical sessions, and collaborative workshops focused on intelligent systems and responsible technology adoption."],schoolInfo:"The School of Science and Computer Studies (SSCS), CMR University, Bengaluru, is a vibrant academic unit committed to delivering high-quality education and research in computing and science disciplines."},d=["CMR University, Bengaluru, is a multidisciplinary private institution established under the CMR University Act, 2013, with a clear focus on delivering quality higher education through innovation and research.","The university offers diverse undergraduate, postgraduate, and doctoral programmes across engineering, management, law, sciences, humanities, economics, education, and design. Its curriculum is outcome-oriented and industry-relevant, emphasizing experiential learning, analytical thinking, and practical application of knowledge.","CMR University encourages interdisciplinary learning through flexible academic structures and choice-based education. Research and innovation are actively promoted through the Directorate of Research and Innovation (DORI), supported by research centers, funded projects, and national and international collaborations.","Strong industry partnerships enhance student exposure through internships, projects, and skill development initiatives. The university also supports entrepreneurship through incubation and startup facilitation while strengthening global engagement through academic partnerships and exchange programmes.","The university cites NAAC accreditation as part of its institutional quality assurance and continuous improvement efforts."],l=e.areas.map(({id:i,title:n,description:t,topics:a})=>({id:i,title:n,description:t,topics:a})),u=[{id:"abstract",title:"Paper Submission Opens",date:"Oct 01, 2026",description:"Submission is open: full papers are submitted through Microsoft CMT."},{id:"full",title:"Full Paper Submission Deadline",date:"Apr 17, 2027",description:"Complete manuscripts due via the submission portal."},{id:"notification",title:"Notification of Acceptance",date:"Jul 31, 2027",description:"Review decisions and feedback released."},{id:"camera",title:"Camera-ready Submission",date:"Aug 11, 2027",description:"Final, formatted manuscripts due for proceedings."},{id:"early",title:"Early Registration Deadline",date:"Sep 04, 2027",description:"Discounted registration closes."},{id:"final",title:"Author Registration Deadline",date:"Sep 04, 2027",description:"Last date to register for in-person attendance."},{id:"conference",title:"Conference Dates",date:"Oct 8-9, 2027",description:"Two-day academic and industry program."}],m=[{title:"Chief Patron",members:[{name:"Dr. Sabitha Ramamurthy",role:"Chancellor",affiliation:"CMR University",url:"https://cmr.edu.in/leadership/",image:"data/cmrapp/image33.png",profileUrl:"https://cmr.edu.in/leadership/",bio:`Dr. Sabitha Ramamurthy is a visionary academic leader and the Chancellor of CMR University. She chose to carry forward the dream of her father-in-law, Sri. Chikka Muniyappa Reddy, whose vision was to educate the masses. When the CMR Jnanadhara Trust was started in 1990, she assumed its leadership as President and began strengthening its educational mission.

Under her guidance, the Trust established the National Junior School, now known as CMR National Public School. What began as a modest school in a family-owned orchard has since developed into a full-fledged CBSE institution known for its steady academic accomplishments.

Her work did not stop with one institution. Through sustained leadership, long-term vision, and a deep commitment to quality education, Dr. Sabitha Ramamurthy has helped shape the growth of the CMR educational ecosystem and continues to inspire academic excellence, institutional development, and holistic learning.`}]},{title:"Conference Patron",members:[{name:"Prof. H. B. Raghavendra",role:"Vice Chancellor",affiliation:"CMR University",image:"data/cmrapp/2.jpg",url:"https://cmr.edu.in/leadership/",profileUrl:"https://cmr.edu.in/leadership/",bio:`Prof. H. B. Raghavendra is the Vice Chancellor of CMR University, Bengaluru. Before joining CMR University, he served in major academic leadership roles including Director and Director General (Vice Chancellor) at Pandit Deendayal Petroleum University, and later as Vice Chancellor at The NorthCap University and Chandigarh University.

He brings more than 35 years of experience in teaching, research, and academic governance. His distinguished leadership profile reflects sustained contributions to higher education administration and institutional growth.

At CMR University, he supports academic excellence, research culture, governance quality, and the advancement of a dynamic and future-oriented university environment.`}]},{title:"Conference Co-Patron",members:[{name:"Dr. Praveen R",role:"Pro-Vice Chancellor",affiliation:"CMR University",url:"https://cmr.edu.in/leadership/",image:"data/cmrapp/3.jpg",profileUrl:"https://cmr.edu.in/leadership/",bio:`Dr. Praveen R serves as Pro-Vice Chancellor of CMR University and oversees key academic and administrative functions of the institution. His responsibilities include policy formulation, regulatory compliance, and the implementation of institutional systems and processes.

He is recognised as a committed academician who combines administrative leadership with scholarly engagement and active participation across academic communities.

His role contributes significantly to strengthening institutional effectiveness, academic coordination, and the overall quality framework that supports teaching, research, and university operations.`}]}],h=[{id:"d1-opening",title:"Inauguration & Welcome Address",track:"Main Ceremony",type:"ceremony",time:"Time to be announced",venue:"CMR University, Bengaluru",day:"day1"},{id:"d1-sessions",title:"Keynotes and technical sessions",track:"All research areas",type:"technical",time:"Time to be announced",venue:"CMR University, Bengaluru",day:"day1",speakers:"The detailed programme will be published after the notification of acceptance (31 July 2027)."},{id:"d2-sessions",title:"Keynotes and technical sessions",track:"All research areas",type:"technical",time:"Time to be announced",venue:"CMR University, Bengaluru",day:"day2",speakers:"The detailed programme will be published after the notification of acceptance (31 July 2027)."},{id:"d2-close",title:"Valedictory & Closing Remarks",track:"Main Ceremony",type:"ceremony",time:"Time to be announced",venue:"CMR University, Bengaluru",day:"day2"}],p=[{id:"student",label:"Student",detail:"UG / PG / Research Scholar",fees:{indian:{ieee:"\u20B97,000",nonIeee:"\u20B98,000"},foreign:{ieee:"US$200",nonIeee:"US$250"}},benefits:["Access to all sessions","Paper presentation","Certificate"]},{id:"academician",label:"Academician",detail:"Faculty and researchers",fees:{indian:{ieee:"\u20B98,000",nonIeee:"\u20B99,000"},foreign:{ieee:"US$250",nonIeee:"US$300"}},benefits:["Access to all sessions","Paper presentation","Certificate & networking"]},{id:"industry",label:"Industry",detail:"Industry professionals",fees:{indian:{ieee:"\u20B910,000",nonIeee:"\u20B912,000"},foreign:{ieee:"US$300",nonIeee:"US$350"}},benefits:["Access to all sessions","Industry networking","Certificate"]}],g=[{question:"Is the conference hybrid?",answer:"No. ICICIC 2027 is an offline conference: papers are presented in person at CMR University, Bengaluru."},{question:"Are submissions required to be original?",answer:"Yes. Submissions must be original, unpublished, and not under review elsewhere."},{question:"How are papers reviewed?",answer:"Each paper is reviewed by experts for originality, technical quality, and relevance to the tracks."},{question:"What is the presentation mode?",answer:"Offline: authors present their papers in person at the venue."},{question:"Do authors receive certificates?",answer:"Yes. All registered presenters receive digital certificates."},{question:"Are proceedings published with ISBN?",answer:"Accepted and registered papers are included in the conference proceedings with ISBN numbers."},{question:"Will there be accommodation guidance?",answer:"Yes. A curated list of nearby hotels and guest houses will be provided to registered attendees."},{question:"Can I change my presentation mode?",answer:"Presentation mode adjustments can be requested up to two weeks before the conference."},{question:"What is the refund policy?",answer:"Refunds are evaluated case-by-case. Contact the organizing team for assistance."},{question:"Are poster sessions included?",answer:"Yes. Dedicated poster sessions are planned for student and early-stage research."}],f=[{title:"Author Ethics & Originality",items:["Submitted work must be original and not under review elsewhere.","Plagiarism screening will be used; submissions failing the similarity checks are rejected.","Authors must accurately cite sources and disclose any conflicts of interest."]},{title:"Code of Conduct & Anti-harassment",items:["ICICIC is committed to a safe, inclusive, and respectful environment.","Harassment, discrimination, or abusive behavior will lead to removal from the event."]},{title:"Presentation & No-show Policy",items:["At least one author must register and present the accepted paper.","No-show papers may be removed from the final proceedings."]},{title:"Privacy & Local Storage",items:["This site uses localStorage to remember theme preferences and saved drafts.","No personal data is transmitted to a server from this website."]}],y=[{tier:"Platinum",description:"Top visibility across keynote sessions and conference collateral.",benefits:["Keynote slot branding","Premium logo placement","VIP networking access"]},{tier:"Gold",description:"Strong visibility across program tracks and digital materials.",benefits:["Logo placement","Exhibition booth","Workshop slot"]},{tier:"Academic Partner",description:"Ideal for institutions supporting research collaboration.",benefits:["Co-branded sessions","Student outreach","Research showcase"]}];export{e as a,c as b,d as c,l as d,u as e,m as f,h as g,p as h,g as i,f as j,y as k};
